use serde::{Serialize, Deserialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TopLevel {
    my_url: String,

    count: i64,

    ratio: f64,

    when: String,

    items: Vec<Item>,

    maybe: Option<serde_json::Value>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Item {
    json_id: i64,

    kind: String,
}

def from_int(x):
    assert isinstance(x, int) and not isinstance(x, bool)
    return x


def from_str(x):
    assert isinstance(x, str)
    return x


def from_float(x):
    assert isinstance(x, (float, int)) and not isinstance(x, bool)
    return float(x)


def from_list(f, x):
    assert isinstance(x, list)
    return [f(y) for y in x]


def from_none(x):
    assert x is None
    return x


def to_float(x):
    assert isinstance(x, (int, float))
    return x


def to_class(c, x):
    assert isinstance(x, c)
    return x.to_dict()


class Item:
    def __init__(self, json_id, kind):
        self.json_id = json_id
        self.kind = kind

    @staticmethod
    def from_dict(obj):
        assert isinstance(obj, dict)
        json_id = from_int(obj["jsonId"])
        kind = from_str(obj["kind"])
        return Item(json_id, kind)

    def to_dict(self):
        result = {}
        result["jsonId"] = from_int(self.json_id)
        result["kind"] = from_str(self.kind)
        return result


class TopLevel:
    def __init__(self, my_url, count, ratio, when, items, maybe):
        self.my_url = my_url
        self.count = count
        self.ratio = ratio
        self.when = when
        self.items = items
        self.maybe = maybe

    @staticmethod
    def from_dict(obj):
        assert isinstance(obj, dict)
        my_url = from_str(obj["myUrl"])
        count = from_int(obj["count"])
        ratio = from_float(obj["ratio"])
        when = from_str(obj["when"])
        items = from_list(Item.from_dict, obj["items"])
        maybe = from_none(obj["maybe"])
        return TopLevel(my_url, count, ratio, when, items, maybe)

    def to_dict(self):
        result = {}
        result["myUrl"] = from_str(self.my_url)
        result["count"] = from_int(self.count)
        result["ratio"] = to_float(self.ratio)
        result["when"] = from_str(self.when)
        result["items"] = from_list(lambda x: to_class(Item, x), self.items)
        result["maybe"] = from_none(self.maybe)
        return result


def top_level_from_dict(s):
    return TopLevel.from_dict(s)


def top_level_to_dict(x):
    return to_class(TopLevel, x)

